"""Small, standard-library-only client for OpenAI's Responses API.

The client reads its API key from ``OPENAI_API_KEY`` by default, sends requests
over HTTPS, and sets ``store`` to ``False`` so responses are not stored for
later API retrieval.  It deliberately does not log prompts, responses, or
credentials.

Example::

    from openai_client import OpenAIResponsesClient

    client = OpenAIResponsesClient()
    answer = client.send("Explain photosynthesis in one sentence.")
    print(answer)

This controls storage through the Responses API.  It is not a promise that
the API provider's operational or safety systems retain no data.
"""

from __future__ import annotations

import json
import os
from typing import Any
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


DEFAULT_ENDPOINT = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4.1-mini"


class OpenAIClientError(RuntimeError):
    """Base exception for errors raised by this module."""


class OpenAIAPIError(OpenAIClientError):
    """The API rejected the request or returned an unusable response."""


class OpenAIResponsesClient:
    """A minimal client for sending text prompts to the Responses API."""

    def __init__(
        self,
        api_key: str | None = None,
        *,
        model: str | None = None,
        timeout: float = 60.0,
        endpoint: str = DEFAULT_ENDPOINT,
    ) -> None:
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("Set OPENAI_API_KEY or pass api_key explicitly.")
        if timeout <= 0:
            raise ValueError("timeout must be greater than zero.")
        if not endpoint.startswith("https://"):
            raise ValueError("endpoint must use HTTPS.")

        self.model = model or os.environ.get("OPENAI_MODEL", DEFAULT_MODEL)
        self.timeout = timeout
        self.endpoint = endpoint

    def send(
        self,
        prompt: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
    ) -> str:
        """Send one private text prompt and return the model's text output.

        Prompt and response contents are kept in memory only by this module;
        callers should also avoid printing or persisting them if they are
        sensitive.
        """
        if not isinstance(prompt, str) or not prompt:
            raise ValueError("prompt must be a non-empty string.")
        if max_output_tokens is not None and (
            not isinstance(max_output_tokens, int) or max_output_tokens <= 0
        ):
            raise ValueError("max_output_tokens must be a positive integer.")

        payload: dict[str, Any] = {
            "model": model or self.model,
            "input": prompt,
            "store": False,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens

        request = Request(
            self.endpoint,
            data=json.dumps(payload).encode("utf-8"),
            headers={
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
                "Accept": "application/json",
            },
            method="POST",
        )

        try:
            with urlopen(request, timeout=self.timeout) as response:
                raw_response = response.read()
        except HTTPError as exc:
            # Do not include the server body: it may contain request data.
            raise OpenAIAPIError(
                f"OpenAI API request failed with HTTP status {exc.code}."
            ) from None
        except URLError as exc:
            raise OpenAIAPIError("Could not reach the OpenAI API.") from exc

        try:
            response_data = json.loads(raw_response.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise OpenAIAPIError("OpenAI API returned invalid JSON.") from exc

        text = _extract_output_text(response_data)
        if text is None:
            raise OpenAIAPIError("OpenAI API response contained no text output.")
        return text


def _extract_output_text(response_data: Any) -> str | None:
    """Extract text from the Responses API's structured output JSON."""
    if not isinstance(response_data, dict):
        return None

    output = response_data.get("output")
    if not isinstance(output, list):
        return None

    parts: list[str] = []
    for item in output:
        if not isinstance(item, dict):
            continue
        content = item.get("content")
        if not isinstance(content, list):
            continue
        for part in content:
            if isinstance(part, dict) and part.get("type") == "output_text":
                text = part.get("text")
                if isinstance(text, str):
                    parts.append(text)
    return "".join(parts) if parts else None


def send_prompt(prompt: str, **kwargs: Any) -> str:
    """Convenience wrapper around :class:`OpenAIResponsesClient`."""
    return OpenAIResponsesClient().send(prompt, **kwargs)


__all__ = [
    "OpenAIAPIError",
    "OpenAIClientError",
    "OpenAIResponsesClient",
    "send_prompt",
]
